macro_rules! deps {
    () => {
        Mode!();
        Hash!();
        HasherExt!();
    };
}

macro_rules! left_subtree_len {
    () => {
        deps!();
        # [doc = " Given the length in bytes of either a complete input or a subtree input, return the number of"] # [doc = " bytes that belong to its left child subtree. The rest belong to its right child subtree."] # [doc = ""] # [doc = " Concretely, this function returns the largest power-of-two number of bytes that's strictly less"] # [doc = " than `input_len`. This leads to a tree where all left subtrees are \"complete\" and at least as"] # [doc = " large as their sibling right subtrees, as specified in section 2.1 of [the BLAKE3"] # [doc = " paper](https://github.com/BLAKE3-team/BLAKE3-specs/blob/master/blake3.pdf). For example, if an"] # [doc = " input is exactly two chunks, the left subtree gets the first chunk and the right subtree gets"] # [doc = " the second chunk. But if an input is two chunks plus one more byte, then its left subtree gets"] # [doc = " two chunks, and its right subtree only gets one byte."] # [doc = ""] # [doc = " This function isn't meaningful for one chunk of input, because chunks don't have children. It"] # [doc = " currently panics in debug mode if `input_len <= CHUNK_LEN`."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " Hash a input of random length as two subtrees:"] # [doc = ""] # [doc = " ```"] # [doc = " # #[cfg(feature = \"std\")] {"] # [doc = " use blake3::hazmat::{left_subtree_len, merge_subtrees_root, HasherExt, Mode};"] # [doc = " use blake3::{Hasher, CHUNK_LEN};"] # [doc = ""] # [doc = " // Generate a random-length input. Note that to be split into two subtrees, the input length"] # [doc = " // must be greater than CHUNK_LEN."] # [doc = " let input_len = rand::random_range(CHUNK_LEN + 1..1_000_000);"] # [doc = " let mut input = vec![0; input_len];"] # [doc = " rand::fill(&mut input[..]);"] # [doc = ""] # [doc = " // Compute the left and right subtree hashes and then the root hash. left_subtree_len() tells"] # [doc = " // us exactly where to split the input. Any other split would either panic (if we're lucky) or"] # [doc = " // lead to an incorrect root hash."] # [doc = " let left_len = left_subtree_len(input_len as u64) as usize;"] # [doc = " let left_subtree_cv = Hasher::new()"] # [doc = "     .update(&input[..left_len])"] # [doc = "     .finalize_non_root();"] # [doc = " let right_subtree_cv = Hasher::new()"] # [doc = "     .set_input_offset(left_len as u64)"] # [doc = "     .update(&input[left_len..])"] # [doc = "     .finalize_non_root();"] # [doc = " let root_hash = merge_subtrees_root(&left_subtree_cv, &right_subtree_cv, Mode::Hash);"] # [doc = ""] # [doc = " // Double check the answer."] # [doc = " assert_eq!(root_hash, blake3::hash(&input));"] # [doc = " # }"] # [doc = " ```"] # [inline (always)] pub fn left_subtree_len (input_len : u64) -> u64 { debug_assert ! (input_len > CHUNK_LEN as u64) ; ((input_len + 1) / 2) . next_power_of_two () }
    };
}

left_subtree_len!()